mapper.select:
SELECT COUNT(*) FROM gw_room_res
 WHERE deleted_at IS NULL
   AND room_id = #{roomId}
   AND end_dt > #{start} AND start_dt < #{end}

   AND res_id <> #{excludeResId}

SELECT 
  FROM gw_room_res r
  JOIN gw_room m ON m.room_id = r.room_id
  JOIN gw_user u ON u.user_id = r.user_id
 WHERE r.deleted_at IS NULL
   AND r.room_id = #{roomId}
   AND r.start_dt < #{to}
   AND r.end_dt   > #{from}
 ORDER BY r.start_dt
